INSERT INTO `recipes` VALUES (1,1,'Fish and Chips 🐟🍟','🐟 For the Fish:\r\n\r\n2–3 pieces of white fish fillets (e.g., dory, snapper, or tilapia) 🐟\r\n\r\n1 cup all-purpose flour 🌾\r\n\r\n1 tsp baking powder 🧪\r\n\r\n1 tsp salt 🧂\r\n\r\n1 tsp black pepper 🌶️\r\n\r\n1 egg 🥚\r\n\r\n1 cup cold sparkling water or beer 🍺\r\n\r\nLemon wedges 🍋\r\n\r\nFresh parsley (optional) 🌿\r\n\r\n🍟 For the Chips:\r\n\r\n2–3 medium-sized potatoes 🥔\r\n\r\nSalt 🧂\r\n\r\nOil for frying (vegetable or sunflower oil) 🌻','1. Prepare the Chips:\r\n\r\nPeel and cut the potatoes into thick strips (chips). 🥔➡️🍟\r\n\r\nRinse and pat them dry with a kitchen towel. 💧➡️🧻\r\n\r\nHeat oil in a deep fryer or large pot to 160°C (320°F). 🔥\r\n\r\nFry the potato strips until they are soft but not browned. Remove and drain on paper towels. 🧻\r\n\r\n2. Prepare the Fish Batter:\r\n\r\nIn a bowl, mix the flour, baking powder, salt, and pepper. 🧂🌾\r\n\r\nAdd the egg and cold sparkling water or beer to the dry ingredients. Stir until the batter is smooth and slightly thick. 🥚🍺➡️🥣\r\n\r\n3. Fry the Fish:\r\n\r\nHeat oil in a deep fryer or large pot to 180°C (350°F). 🔥\r\n\r\nDip each fish fillet into the batter, ensuring it\'s fully coated. 🐟➡️🥣\r\n\r\nCarefully lower the battered fillets into the hot oil. Fry until golden brown and crispy, about 4–5 minutes. 🕒\r\n\r\nRemove and drain on paper towels. 🧻\r\n\r\n4. Double Fry the Chips:\r\n\r\nIncrease the oil temperature to 190°C (375°F). 🔥\r\n\r\nFry the pre-cooked potato strips again until they are golden brown and crispy. 🕒\r\n\r\nRemove and drain on paper towels. 🧻\r\n\r\nSeason with salt to taste. 🧂\r\n\r\n5. Serve:\r\n\r\nPlate the crispy fish fillets and golden chips. 🍽️\r\n\r\nGarnish with lemon wedges and fresh parsley if desired. 🍋🌿\r\n\r\nServe with tartar sauce or your favorite dipping sauce. 🥣\r\n\r\n🍴 Enjoy Your Meal!\r\n\r\nDig in and savor the crispy, golden goodness of homemade fish and chips! 😋🍽️',30,NULL,'2025-10-06 07:10:28.610083','2025-10-06 07:10:29.435876',NULL,NULL,NULL),(2,1,'Cheesy Loaded Nachos 🧀','🥩 Untuk Daging:\r\n\r\n500g–1kg daging cincang\r\n\r\nGaram secukup rasa\r\n\r\nBlack pepper secukup rasa\r\n\r\nGarlic powder secukup rasa\r\n\r\n🧀 Untuk Sos Keju:\r\n\r\n2 sudu besar plain yogurt\r\n\r\n4–5 keping keju cheddar (atau lebih, ikut citarasa)\r\n\r\nSusu secukupnya\r\n\r\nChili powder secukup rasa\r\n\r\nGaram secukup rasa\r\n\r\n🌮 Untuk Nachos:\r\n\r\nTortilla chips secukupnya\r\n\r\nBawang merah, dipotong dadu\r\n\r\nTomato segar, dipotong dadu\r\n\r\nSos hijau (green sauce) secukupnya\r\n\r\nKeju nachos secukupnya','Masak Daging:\r\n\r\nPanaskan sedikit minyak dalam kuali.\r\n\r\nMasukkan daging cincang, garam, black pepper, dan garlic powder.\r\n\r\nTumis hingga daging masak dan berwarna perang.\r\n\r\nSos Keju:\r\n\r\nDalam periuk kecil, campurkan plain yogurt dan susu.\r\n\r\nPanaskan hingga mendidih perlahan.\r\n\r\nMasukkan kepingan keju cheddar dan kacau hingga keju cair sepenuhnya.\r\n\r\nTambahkan chili powder dan garam secukup rasa.\r\n\r\nPenyusunan Nachos:\r\n\r\nSusun tortilla chips di atas dulang pembakar.\r\n\r\nTaburkan daging masak, bawang merah, tomato, dan sos hijau di atas chips.\r\n\r\nTuangkan sos keju di atasnya.\r\n\r\nTaburkan keju nachos secukupnya.\r\n\r\nPembakaran:\r\n\r\nPanaskan oven pada suhu 180°C.\r\n\r\nBakar nachos selama 10–15 minit atau sehingga keju cair dan berbuih.\r\n\r\nHidangan:\r\n\r\nKeluarkan nachos dari oven dan hidangkan panas-panas.',35,NULL,'2025-10-06 07:14:57.657691','2025-10-06 07:14:57.835537',NULL,NULL,NULL),(3,1,'Habanero Honey Chicken Tenders 🐔','🍗 Ayam:\r\n\r\n500g isi ayam (potong memanjang) 🍗\r\n\r\n1 cawan Tepung Ayam Spicy Bon Chef 🌶️\r\n\r\n1/3 cawan tepung beras 🌾\r\n\r\n1 mangkuk air sejuk ❄️💧\r\n\r\n🍯 Sos Madu Habanero:\r\n\r\n4–5 sudu besar mentega 🧈\r\n\r\n1 sudu kecil serbuk bawang putih 🧄\r\n\r\n1 sudu kecil paprika 🌶️\r\n\r\n1 sudu besar madu 🍯\r\n\r\n🥣 Sos Bawang Putih (Garlic Sauce):\r\n\r\n3 sudu besar plain yogurt 🥛\r\n\r\n2 sudu besar mayonis 🥄\r\n\r\n1/2 sudu kecil serbuk lada hitam 🌶️\r\n\r\n1/2 sudu kecil serbuk bawang putih 🧄\r\n\r\n1/2 sudu kecil mixed herbs 🌿\r\n\r\nSedikit jus lemon 🍋','Sediakan Ayam:\r\n\r\nCampurkan isi ayam 🍗 dengan Tepung Ayam Spicy Bon Chef 🌶️ dan tepung beras 🌾.\r\n\r\nTambahkan air sejuk ❄️ sedikit demi sedikit hingga adunan melekat pada ayam.\r\n\r\nGoreng Ayam:\r\n\r\nPanaskan minyak dalam kuali 🔥.\r\n\r\nGoreng ayam hingga keemasan dan rangup 🍗✨.\r\n\r\nAngkat dan toskan minyak berlebihan 🧻.\r\n\r\nSediakan Sos Madu Habanero:\r\n\r\nLelehkan mentega 🧈 dalam kuali.\r\n\r\nMasukkan serbuk bawang putih 🧄 dan paprika 🌶️, kacau sebati.\r\n\r\nTambahkan madu 🍯 dan kacau hingga sos sebati.\r\n\r\nSediakan Sos Bawang Putih:\r\n\r\nCampurkan yogurt 🥛, mayonis 🥄, lada hitam 🌶️, serbuk bawang putih 🧄, mixed herbs 🌿, dan jus lemon 🍋 dalam mangkuk.\r\n\r\nKacau hingga rata.\r\n\r\nHidangkan:\r\n\r\nSusun ayam 🍗 di atas pinggan 🍽️.\r\n\r\nTuangkan sos madu habanero 🍯🔥 di atas ayam.\r\n\r\nSajikan bersama sos bawang putih 🥣 sebagai pencicah.\r\n\r\n😋 Tips:\r\n\r\nHidangkan panas-panas untuk rasa yang paling sedap 🔥🍗.\r\n\r\nBoleh tambah salad segar 🥗 untuk seimbang dengan pedas manisnya.',35,NULL,'2025-10-06 07:16:01.160014','2025-10-06 07:16:01.345121',NULL,NULL,NULL),(4,1,'Macaroni & Cheese 🧀','🍝 Untuk Macaroni:\r\n\r\n1.5 cawan macaroni\r\n\r\n2 cawan susu segar\r\n\r\n1 cawan air\r\n\r\n7 keping keju cheddar\r\n\r\nGaram secukup rasa\r\n\r\nMentega\r\n\r\nSerbuk roti\r\n\r\n🧂 Untuk Topping:\r\n\r\n1 cawan panko breadcrumbs\r\n\r\n1/2 sudu teh lada hitam\r\n\r\n1/2 sudu kecil garam\r\n\r\n1 cawan keju Colby, diparut\r\n\r\n1 sudu kering oregano','Masak Macaroni:\r\n\r\nDidihkan air dalam periuk besar.\r\n\r\nMasukkan macaroni dan masak hingga al dente.\r\n\r\nToskan dan ketepikan.\r\n\r\nSediakan Sos Keju:\r\n\r\nDalam periuk, panaskan susu dan air.\r\n\r\nMasukkan keju cheddar dan kacau hingga keju cair sepenuhnya.\r\n\r\nTambahkan garam secukup rasa.\r\n\r\nGabungkan Macaroni dan Sos:\r\n\r\nMasukkan macaroni yang telah dimasak ke dalam sos keju.\r\n\r\nGaul rata hingga semua macaroni disaluti sos keju.\r\n\r\nSediakan Topping:\r\n\r\nDalam mangkuk, campurkan panko breadcrumbs, lada hitam, garam, keju Colby, dan oregano.\r\n\r\nTaburkan campuran topping di atas macaroni.\r\n\r\nBakar Mac & Cheese:\r\n\r\nPanaskan oven pada suhu 180°C.\r\n\r\nBakar macaroni selama 10–15 minit atau hingga permukaan keemasan.\r\n\r\nHidangkan:\r\n\r\nKeluarkan dari oven dan biarkan sejuk seketika.\r\n\r\nSedia untuk dinikmati!',28,NULL,'2025-10-06 07:19:10.696522','2025-10-06 07:19:10.967833',NULL,NULL,NULL),(5,1,'Buffalo Wings 🍗🔥','🧄 3 cloves garlic, minced\r\n\r\n🌶️ 1½ cups Frank\'s RedHot Original sauce\r\n\r\n🧈 4 oz (1 stick) cold unsalted butter\r\n\r\n🍯 2 tbsp honey\r\n\r\n🧂 1 tbsp oil\r\n\r\n🧂 Salt and black pepper to taste\r\n\r\n🍗 10–12 chicken wings\r\n\r\n🥕 Celery sticks and ranch or blue cheese dressing for dipping','Prepare the Wings:\r\n\r\nPat the chicken wings dry with paper towels.\r\n\r\nSeason with salt and black pepper.\r\n\r\nPreheat the oven to 200°C (400°F).\r\n\r\nPlace the wings on a baking sheet lined with parchment paper.\r\n\r\nBake for 25–30 minutes, flipping halfway through, until golden and crispy.\r\n\r\nMake the Buffalo Sauce:\r\n\r\nIn a saucepan, heat the oil over medium heat.\r\n\r\nAdd the minced garlic and sauté until fragrant.\r\n\r\nPour in the Frank\'s RedHot sauce and bring to a simmer.\r\n\r\nReduce heat and whisk in the cold butter until melted and the sauce is smooth.\r\n\r\nStir in the honey and season with salt and black pepper to taste.\r\n\r\nCoat the Wings:\r\n\r\nOnce the wings are cooked, remove them from the oven.\r\n\r\nPlace the wings in a large bowl.\r\n\r\nPour the buffalo sauce over the wings and toss to coat evenly.\r\n\r\nServe:\r\n\r\nArrange the buffalo wings on a serving platter.\r\n\r\nServe with celery sticks and your choice of dipping sauce.',25,NULL,'2025-10-06 07:20:37.803622','2025-10-06 07:20:37.993976',NULL,NULL,NULL),(6,1,'🍝 Spaghetti Bolognese','🍝 300g spaghetti\r\n\r\n🥩 400g ground beef\r\n\r\n🧄 3 cloves garlic, minced\r\n\r\n🧅 1 onion, finely chopped\r\n\r\n🍅 400g canned diced tomatoes\r\n\r\n🍅 2 tbsp tomato paste\r\n\r\n🥕 1 carrot, finely diced\r\n\r\n🌿 1 tsp dried oregano\r\n\r\n🌿 1 tsp dried basil\r\n\r\n🧂 Salt and pepper, to taste\r\n\r\n🫒 2 tbsp olive oil\r\n\r\n🧀 Grated Parmesan, for serving','Cook Spaghetti:\r\n\r\nBoil water in a large pot 💧🔥\r\n\r\nAdd a pinch of salt 🧂\r\n\r\nCook spaghetti 🍝 according to package instructions until al dente ✅\r\n\r\nDrain and set aside 🥣\r\n\r\nCook the Sauce:\r\n\r\nHeat olive oil 🫒 in a large pan over medium heat 🔥\r\n\r\nSauté onions 🧅 and garlic 🧄 until soft and fragrant ✨\r\n\r\nAdd ground beef 🥩, cook until browned, breaking up lumps with a spoon 🍴\r\n\r\nAdd Vegetables & Tomatoes:\r\n\r\nStir in diced carrot 🥕 and cook for 2–3 minutes\r\n\r\nAdd diced tomatoes 🍅 and tomato paste 🍅\r\n\r\nSeason with salt 🧂, pepper 🌶️, oregano 🌿, and basil 🌿\r\n\r\nSimmer on low heat for 20–25 minutes, stirring occasionally 🔄\r\n\r\nCombine & Serve:\r\n\r\nToss cooked spaghetti 🍝 with Bolognese sauce 🥩🍅\r\n\r\nServe hot with grated Parmesan 🧀 on top\r\n\r\nOptional: garnish with fresh basil 🌿\r\n\r\n😋 Tips:\r\n\r\nLet the sauce simmer longer for richer flavor 🍅🔥\r\n\r\nAdd a splash of red wine 🍷 for extra depth (optional)',45,NULL,'2025-10-06 07:21:30.432579','2025-10-06 07:21:30.625371',NULL,NULL,NULL),(7,1,'🍝 Gigi Hadid’s Spicy Pasta','3 tablespoons olive oil\r\n\r\n1/3 medium onion, finely chopped\r\n\r\n3 cloves garlic, minced\r\n\r\n1½ teaspoons red pepper flakes (adjust to taste)\r\n\r\n¼ cup tomato paste\r\n\r\n½ cup heavy cream\r\n\r\n1 tablespoon butter\r\n\r\nSalt and black pepper, to taste\r\n\r\n300g pasta (penne or rigatoni recommended)\r\n\r\n¼ cup pasta water (reserved)\r\n\r\n¼ cup grated Parmesan cheese\r\n\r\nFresh basil leaves (optional, for garnish)','Cook the Pasta:\r\n\r\nBoil water in a large pot and cook the pasta according to package instructions until al dente.\r\n\r\nReserve ¼ cup of pasta water before draining.\r\n\r\nPrepare the Sauce:\r\n\r\nIn a large skillet, heat olive oil over medium heat.\r\n\r\nAdd chopped onion and sauté until translucent.\r\n\r\nAdd minced garlic and red pepper flakes; cook until fragrant.\r\n\r\nStir in tomato paste and cook for 2–3 minutes.\r\n\r\nPour in heavy cream and bring to a simmer.\r\n\r\nSeason with salt and black pepper to taste.\r\n\r\nCombine Pasta and Sauce:\r\n\r\nAdd the cooked pasta to the sauce, tossing to coat evenly.\r\n\r\nPour in reserved pasta water and butter; stir until the sauce is creamy and well-combined.\r\n\r\nStir in grated Parmesan cheese until melted and smooth.\r\n\r\nServe:\r\n\r\nPlate the pasta and garnish with fresh basil leaves, if desired.\r\n\r\nServe immediately and enjoy!',30,NULL,'2025-10-06 07:22:27.997237','2025-10-06 07:22:28.151952',NULL,NULL,NULL),(8,1,'🍝 Spaghetti Carbonara','🍝 200g spaghetti\r\n\r\n🥓 100g beef strips (or bacon)\r\n\r\n🧈 1 tablespoon butter\r\n\r\n🧄 2 cloves garlic, minced\r\n\r\n🥚 2 large eggs\r\n\r\n🧀 ½ cup grated Parmesan cheese\r\n\r\n🧂 Salt and black pepper, to taste\r\n\r\n🧂 1 teaspoon salt (for pasta water)\r\n\r\n🌿 Fresh parsley (optional, for garnish)','ook the Spaghetti:\r\n\r\nBoil water in a large pot and add 1 teaspoon of salt.\r\n\r\nCook spaghetti according to package instructions until al dente.\r\n\r\nReserve ½ cup of pasta water before draining.\r\n\r\nPrepare the Sauce:\r\n\r\nIn a bowl, whisk together eggs, grated Parmesan, salt, and black pepper until well combined.\r\n\r\nCook the Beef Strips:\r\n\r\nHeat butter in a pan over medium heat.\r\n\r\nAdd minced garlic and sauté until fragrant.\r\n\r\nAdd beef strips and cook until browned.\r\n\r\nCombine Pasta and Sauce:\r\n\r\nAdd cooked spaghetti to the pan with beef and garlic.\r\n\r\nPour the egg and cheese mixture over the pasta, tossing quickly to create a creamy sauce.\r\n\r\nIf the sauce is too thick, add reserved pasta water a little at a time until desired consistency is reached.\r\n\r\nServe:\r\n\r\nPlate the pasta and garnish with fresh parsley, if desired.\r\n\r\nServe immediately and enjoy!',20,NULL,'2025-10-06 07:25:02.555299','2025-10-06 07:25:02.715228',NULL,NULL,NULL),(9,1,'🍝 Creamy Tomyam Pasta','🍝 200g spaghetti\r\n\r\n🧅 1 medium onion, finely chopped\r\n\r\n🧄 5 cloves garlic, minced\r\n\r\n🍤 100g prawns (or your choice of protein)\r\n\r\n🌶️ 1 tbsp tomyam paste (e.g., Adabi)\r\n\r\n🥛 ½ cup fresh milk\r\n\r\n🧈 ½ cup cooking cream\r\n\r\n🍋 2–3 kaffir lime leaves, torn\r\n\r\n🌶️ 2–3 red bird\'s eye chilies, sliced\r\n\r\n🍅 2–3 cherry tomatoes, halved\r\n\r\n🧂 1 tsp chicken stock cube\r\n\r\n🧂 Salt and sugar, to taste\r\n\r\n🌿 Fresh parsley or coriander, for garnish (optional)','Cook the Spaghetti:\r\n\r\nBoil water in a large pot, adding a pinch of salt.\r\n\r\nCook spaghetti according to package instructions until al dente.\r\n\r\nReserve ½ cup of pasta water before draining.\r\n\r\nPrepare the Sauce:\r\n\r\nIn a pan, heat a bit of oil over medium heat.\r\n\r\nSauté chopped onion and minced garlic until fragrant.\r\n\r\nAdd prawns and cook until they turn pink.\r\n\r\nStir in tomyam paste and cook for 1–2 minutes.\r\n\r\nPour in fresh milk and cooking cream, stirring to combine.\r\n\r\nAdd kaffir lime leaves, sliced chilies, cherry tomatoes, and chicken stock cube.\r\n\r\nSeason with salt and sugar to taste.\r\n\r\nLet the sauce simmer for 5–7 minutes until it thickens slightly.\r\n\r\nCombine Pasta and Sauce:\r\n\r\nAdd the cooked spaghetti to the sauce, tossing to coat evenly.\r\n\r\nIf the sauce is too thick, add reserved pasta water a little at a time until desired consistency is reached.\r\n\r\nServe:\r\n\r\nPlate the pasta and garnish with fresh herbs, if desired.\r\n\r\nServe immediately and enjoy!',20,NULL,'2025-10-06 07:27:04.654926','2025-10-06 07:27:04.828174',NULL,NULL,NULL),(10,1,'🍄 Creamy Mushroom Soup & 🥖 Garlic Bread','🍄 Mushroom Soup\r\n\r\n2 tbsp butter 🧈\r\n\r\n½ onion (diced) 🧅\r\n\r\n2 cloves garlic (minced) 🧄\r\n\r\n200g shiitake mushrooms (sliced) 🍄\r\n\r\n2 tbsp all-purpose flour 🌾\r\n\r\n200–300ml cooking cream or full cream milk 🥛\r\n\r\n1 cup water 💧\r\n\r\n1 chicken stock cube 🍗\r\n\r\n½ tsp black pepper 🌶️\r\n\r\nSalt to taste 🧂\r\n\r\nFresh parsley (optional, for garnish) 🌿\r\n\r\n🥖 Garlic Bread\r\n\r\nBread slices (baguette or any preferred type) 🍞\r\n\r\nButter (softened) 🧈\r\n\r\n5 cloves garlic (minced) 🧄\r\n\r\nDried oregano (optional) 🌿','🍄 Mushroom Soup\r\n\r\nSauté Aromatics: Melt butter in a pot over medium heat. Add diced onion and minced garlic, sautéing until fragrant.\r\n\r\nCook Mushrooms: Add sliced shiitake mushrooms to the pot, cooking until they release their juices and soften.\r\n\r\nAdd Flour: Stir in the flour, cooking for 1–2 minutes to form a roux.\r\n\r\nSimmer: Pour in water, cooking cream, and add the chicken stock cube. Stir well and bring to a simmer.\r\n\r\nSeason: Add black pepper and salt to taste. Let the soup simmer for 5–7 minutes, allowing flavors to meld.\r\n\r\nBlend (Optional): For a smoother texture, blend the soup until desired consistency is achieved.\r\n\r\nServe: Ladle the soup into bowls and garnish with fresh parsley if desired.\r\n\r\n🥖 Garlic Bread\r\n\r\nPrepare Butter Mixture: In a bowl, mix softened butter with minced garlic and dried oregano until well combined.\r\n\r\nSpread on Bread: Generously spread the garlic butter mixture onto each slice of bread.\r\n\r\nToast: Place the prepared bread slices on a baking tray and toast in a preheated oven at 180°C (350°F) for 10–12 minutes, or until golden brown and crispy.\r\n\r\nServe: Serve the garlic bread warm alongside the creamy mushroom soup.',20,NULL,'2025-10-06 07:28:17.342145','2025-10-06 07:28:17.517694',NULL,NULL,1),(11,3,'Soft & Chewy Cookies🍪✨','1 cup (225g) unsalted butter, softened 🧈\r\n\r\n1 cup (200g) brown sugar 🤎\r\n\r\n½ cup (100g) granulated sugar 🤍\r\n\r\n2 large eggs 🥚🥚\r\n\r\n1 tsp vanilla extract 🍦\r\n\r\n2 ½ cups (320g) all-purpose flour 🌾\r\n\r\n1 tsp baking soda 🥄\r\n\r\n½ tsp salt 🧂\r\n\r\n2 cups (350g) chocolate chips 🍫','Preheat & Prep 🔥\r\nPreheat oven to 175°C (350°F). Line a baking tray with parchment paper.\r\n\r\nCream Butter & Sugar 🥄\r\nIn a large bowl, beat butter + brown sugar + granulated sugar until light and fluffy.\r\n\r\nAdd Eggs & Vanilla 🥚\r\nBeat in eggs one at a time, then add vanilla extract.\r\n\r\nMix Dry Ingredients 🌾\r\nIn a separate bowl, whisk flour + baking soda + salt. Gradually mix into wet ingredients.\r\n\r\nAdd Chocolate Chips 🍫\r\nFold in chocolate chips gently.\r\n\r\nScoop & Bake 🍪\r\nDrop spoonfuls of dough onto the baking tray (about 2 inches apart). Bake for 10–12 minutes until edges are lightly golden.\r\n\r\nCool & Enjoy 😋\r\nLet cookies cool on tray for 5 min, then transfer to wire rack. Soft, chewy, and ready to snack! 🥰',35,NULL,'2025-10-06 07:37:46.701811','2025-10-06 07:37:47.319844',NULL,NULL,NULL),(12,3,'Tiramisu ☕🍰','3 large eggs 🥚🥚🥚\r\n\r\n1/2 cup (100g) sugar 🤍\r\n\r\n1 cup (240ml) heavy cream 🥛\r\n\r\n1 tsp vanilla extract 🍦\r\n\r\n8 oz (225g) mascarpone cheese 🧀\r\n\r\n1 cup (240ml) brewed coffee ☕, cooled\r\n\r\n2 tbsp coffee liqueur 🍸 (optional)\r\n\r\n24–30 ladyfinger biscuits 🍪\r\n\r\nUnsweetened cocoa powder 🍫 for dusting\r\n\r\nChocolate shavings 🍫✨ (optional)','Prepare Coffee ☕\r\nBrew coffee and let it cool. Mix in coffee liqueur if using.\r\n\r\nWhip Eggs & Sugar 🥚🤍\r\nIn a bowl, whisk eggs + sugar until pale and fluffy (about 3–5 min).\r\n\r\nMix Mascarpone & Cream 🧀🥛\r\nIn another bowl, whip heavy cream + vanilla until soft peaks form. Fold in mascarpone gently.\r\n\r\nCombine Mixtures 💕\r\nFold the egg mixture into mascarpone cream until smooth.\r\n\r\nLayer Ladyfingers 🍪\r\nQuickly dip each ladyfinger into coffee (don’t soak!) and line the bottom of a dish.\r\n\r\nAdd Cream Layer 🥄\r\nSpread half of the mascarpone mixture over the ladyfingers. Repeat layers (ladyfingers + cream).\r\n\r\nChill ❄️\r\nCover and refrigerate for 4–6 hours (or overnight) to set.\r\n\r\nDecorate & Serve 🍫✨\r\nDust with cocoa powder and sprinkle chocolate shavings. Optional: add cute fruit like strawberries 🍓 on top.',20,NULL,'2025-10-06 07:40:49.065235','2025-10-06 07:40:49.250470',NULL,NULL,NULL),(13,3,'Chocolate Éclairs 🍫🥖','For the Choux Pastry:\r\n\r\n1/2 cup (120ml) water 💧\r\n\r\n1/2 cup (120ml) milk 🥛\r\n\r\n1/2 cup (115g) unsalted butter 🧈\r\n\r\n1 tbsp sugar 🤍\r\n\r\n1/4 tsp salt 🧂\r\n\r\n1 cup (125g) all-purpose flour 🌾\r\n\r\n4 large eggs 🥚🥚🥚🥚\r\n\r\nFor the Pastry Cream:\r\n\r\n2 cups (480ml) milk 🥛\r\n\r\n1/2 cup (100g) sugar 🤍\r\n\r\n4 large egg yolks 🥚🥚🥚🥚\r\n\r\n1/4 cup (30g) cornstarch 🌾\r\n\r\n2 tsp vanilla extract 🍦\r\n\r\n2 tbsp butter 🧈\r\n\r\nFor the Chocolate Glaze:\r\n\r\n4 oz (115g) dark chocolate 🍫\r\n\r\n1/2 cup (120ml) heavy cream 🥛','Make Choux Pastry 🥖\r\n\r\nPreheat oven to 200°C (400°F) 🔥.\r\n\r\nIn a saucepan, heat water + milk + butter + sugar + salt until boiling.\r\n\r\nRemove from heat and stir in flour until smooth 🌾.\r\n\r\nCool slightly, then beat in eggs one at a time 🥚.\r\n\r\nPipe onto a baking sheet in 4-inch logs 🍥.\r\n\r\nBake 20–25 min until golden and puffed. Cool completely.\r\n\r\nMake Pastry Cream 🍮\r\n\r\nHeat milk until steaming 🥛.\r\n\r\nWhisk egg yolks + sugar + cornstarch in a bowl.\r\n\r\nSlowly pour hot milk into egg mixture while whisking 💕.\r\n\r\nReturn to heat, cook until thick. Stir in butter + vanilla. Chill. ❄️\r\n\r\nFill Éclairs 🥄\r\n\r\nCut cooled éclairs in half or make a small hole.\r\n\r\nPipe in chilled pastry cream.\r\n\r\nMake Chocolate Glaze 🍫\r\n\r\nHeat cream until simmering 🥛.\r\n\r\nPour over chopped chocolate and stir until smooth.\r\n\r\nDip top of éclairs into chocolate.\r\n\r\nServe & Enjoy 😋\r\n\r\nChill for 10–15 min so glaze sets.\r\n\r\nShare and enjoy your cute chocolate éclairs! 💖',40,NULL,'2025-10-06 07:43:02.519821','2025-10-06 07:43:02.691306',NULL,NULL,NULL),(14,3,'🍫🍪 No-Bake Chocolate Biscuit Rolls','200g plain tea biscuits 🍪\r\n\r\n100g unsalted butter 🧈\r\n\r\n100g dark chocolate 🍫\r\n\r\n1/2 cup (50g) powdered sugar 🤍\r\n\r\n2 tbsp cocoa powder 🍫\r\n\r\n1/4 cup milk 🥛\r\n\r\n1 tsp vanilla extract 🍦\r\n\r\nDesiccated coconut or sprinkles 🌈 (optional)','Prepare Chocolate Mixture 🍫\r\n\r\nMelt butter + chocolate in a saucepan over low heat 🔥.\r\n\r\nStir in milk, powdered sugar, cocoa powder, and vanilla until smooth.\r\n\r\nCrush Biscuits 🍪\r\n\r\nBreak biscuits into small pieces (not too fine) in a large bowl.\r\n\r\nCombine 💕\r\n\r\nPour chocolate mixture over crushed biscuits. Mix until all biscuits are coated.\r\n\r\nShape Rolls 🌀\r\n\r\nPlace mixture on a sheet of cling film.\r\n\r\nRoll tightly into a log shape (like a Swiss roll).\r\n\r\nChill ❄️\r\n\r\nRefrigerate for 1–2 hours until firm.\r\n\r\nServe & Decorate ✨\r\n\r\nSlice into 1–2 cm pieces.\r\n\r\nOptional: roll in desiccated coconut or sprinkles 🌈.\r\n\r\nEnjoy! 😋\r\n\r\nSoft, chocolatey, and super cute for snacks or parties! 💖',20,NULL,'2025-10-06 07:46:54.188516','2025-10-06 07:46:54.371977',NULL,NULL,NULL),(15,3,'🍩🌟 Crispy & Soft Churros ✨','1 cup (120g) all-purpose flour 🌾\r\n\r\n1 cup (240ml) water 💧\r\n\r\n2 tbsp sugar 🤍\r\n\r\n2 tbsp unsalted butter 🧈\r\n\r\n1/4 tsp salt 🧂\r\n\r\n1/2 tsp vanilla extract 🍦\r\n\r\n2 large eggs 🥚🥚\r\n\r\nOil for frying 🛢️\r\n\r\nCinnamon sugar for coating 🤎✨\r\n\r\nOptional Chocolate Dip:\r\n\r\n100g dark chocolate 🍫\r\n\r\n1/4 cup (60ml) heavy cream 🥛','Prepare Dough 🌾🥄\r\n\r\nIn a saucepan, heat water + butter + sugar + salt until boiling.\r\n\r\nRemove from heat, add flour all at once, stir until mixture forms a ball.\r\n\r\nAdd Eggs 🥚\r\n\r\nLet dough cool slightly. Beat in eggs one at a time until smooth and glossy.\r\n\r\nPipe Churros 🌀\r\n\r\nTransfer dough to a piping bag with a star tip.\r\n\r\nPipe 4–6 inch strips onto parchment paper.\r\n\r\nFry Churros 🍩🔥\r\n\r\nHeat oil to 180°C (350°F).\r\n\r\nFry churros until golden brown (2–3 min per side). Drain on paper towels.\r\n\r\nCoat with Cinnamon Sugar 🤎✨\r\n\r\nMix sugar + cinnamon. Roll warm churros in mixture.\r\n\r\nOptional Chocolate Dip 🍫🥛\r\n\r\nMelt chocolate with cream, stir until smooth. Serve churros with chocolate dip.\r\n\r\nEnjoy! 😋\r\n\r\nCrispy outside, soft inside, and perfect for snacking! 💖',30,NULL,'2025-10-06 07:48:48.040254','2025-10-06 08:32:01.753098',NULL,NULL,NULL),(16,3,'🌀🍥 Soft & Sweet Cinnamon Rolls ✨','For the Dough:\r\n\r\n2 1/4 tsp (1 packet) active dry yeast 🍞\r\n\r\n1/4 cup (60ml) warm water 💧\r\n\r\n1/2 cup (120ml) milk 🥛\r\n\r\n1/4 cup (50g) sugar 🤍\r\n\r\n1/4 cup (60g) unsalted butter, melted 🧈\r\n\r\n1 tsp salt 🧂\r\n\r\n1 large egg 🥚\r\n\r\n2 1/2 cups (320g) all-purpose flour 🌾\r\n\r\nFor the Filling:\r\n\r\n1/2 cup (100g) brown sugar 🤎\r\n\r\n2 tbsp cinnamon 🌿\r\n\r\n1/4 cup (60g) butter, softened 🧈\r\n\r\nFor the Glaze:\r\n\r\n1 cup (120g) powdered sugar 🤍\r\n\r\n2 tbsp milk 🥛\r\n\r\n1/2 tsp vanilla extract 🍦','Prepare Dough 🍞\r\n\r\nDissolve yeast in warm water and let sit 5 min.\r\n\r\nMix in milk, sugar, melted butter, egg, and salt. Gradually add flour until soft dough forms.\r\n\r\nKnead 5–7 min until smooth.\r\n\r\nLet Dough Rise ⏱\r\n\r\nCover with a cloth and let it rise in a warm place for 1–2 hrs until doubled in size.\r\n\r\nPrepare Filling 🤎🧈\r\n\r\nMix brown sugar + cinnamon. Spread softened butter on rolled-out dough and sprinkle filling evenly.\r\n\r\nRoll & Slice 🌀\r\n\r\nRoll dough into a log and slice into 8 rolls. Place in a greased baking dish.\r\n\r\nSecond Rise ⏱\r\n\r\nCover and let rolls rise 30 min.\r\n\r\nBake 🔥\r\n\r\nPreheat oven to 180°C (350°F). Bake 20–25 min until golden brown.\r\n\r\nGlaze & Serve 🍦\r\n\r\nMix powdered sugar + milk + vanilla. Drizzle over warm rolls. Enjoy soft, sweet, and cinnamony goodness! 😋💖',25,NULL,'2025-10-06 08:35:46.556007','2025-10-06 08:35:46.948065',NULL,NULL,NULL),(17,3,'🍌🍮 Classic Banana Pudding ✨','3–4 ripe bananas 🍌\r\n\r\n1 box (3.4 oz / 96g) instant vanilla pudding mix 🍮\r\n\r\n2 cups (480ml) cold milk 🥛\r\n\r\n1 can (14 oz / 396g) sweetened condensed milk 🤍\r\n\r\n1 tsp vanilla extract 🍦\r\n\r\n1 cup (240ml) heavy cream 🥛\r\n\r\n1/4 cup powdered sugar 🤍\r\n\r\n1 box (11 oz / 312g) vanilla wafers 🍪','Prepare Pudding 🍮\r\n\r\nIn a bowl, whisk pudding mix + cold milk until thickened.\r\n\r\nStir in sweetened condensed milk + vanilla.\r\n\r\nWhip Cream 🥛\r\n\r\nIn another bowl, whip heavy cream + powdered sugar until soft peaks form.\r\n\r\nFold whipped cream into pudding gently 💕.\r\n\r\nLayer Dessert 🍌\r\n\r\nIn a serving dish or individual cups:\r\n\r\nLayer vanilla wafers 🍪\r\n\r\nSlice bananas 🍌 and layer on top\r\n\r\nSpread pudding mixture over bananas\r\n\r\nRepeat layers until dish is full\r\n\r\nChill ❄️\r\n\r\nRefrigerate 2–3 hours until set.\r\n\r\nServe & Enjoy 😋\r\n\r\nOptional: Top with extra wafers 🍪, banana slices 🍌, or a sprinkle of cinnamon 🌿.',15,NULL,'2025-10-06 08:38:24.470200','2025-10-06 08:38:24.692533',NULL,NULL,NULL),(18,4,'🍜 Jjajangmyeon (Korean Black Bean Paste Noodles)','🍜 200g fresh or dried Korean wheat noodles (jjajangmyeon noodles)\r\n\r\n🥩 150g meat or chicken breast, diced\r\n\r\n🧅 1 medium onion, diced\r\n\r\n🥕 ½ carrot, julienned\r\n\r\n🧄 2 cloves garlic, minced\r\n\r\n🧄 1 tablespoon ginger, minced\r\n\r\n🧂 2 tablespoons vegetable oil\r\n\r\n🍜 3 tablespoons Korean black bean paste (chunjang)\r\n\r\n🥄 1 tablespoon sugar\r\n\r\n🍶 1 tablespoon soy sauce\r\n\r\n💧 1½ cups water\r\n\r\n🥄 1 tablespoon cornstarch mixed with 2 tablespoons water (for slurry)\r\n\r\n🧂 Salt and pepper, to taste\r\n\r\n🌿 Cucumber slices, for garnish (optional)','Cook the Noodles:\r\n\r\nBoil water in a pot and cook the noodles according to package instructions. Drain and set aside.\r\n\r\nPrepare the Sauce:\r\n\r\nIn a pan, heat vegetable oil over medium heat.\r\n\r\nAdd diced pork belly or chicken and cook until browned.\r\n\r\nAdd diced onion, julienned carrot, minced garlic, and minced ginger. Sauté until vegetables are tender.\r\n\r\nStir in the black bean paste and cook for 2–3 minutes.\r\n\r\nAdd sugar, soy sauce, and water. Bring to a boil, then reduce heat and simmer for 5 minutes.\r\n\r\nAdd the cornstarch slurry to the sauce and stir until it thickens. Season with salt and pepper to taste.\r\n\r\nCombine and Serve:\r\n\r\nPlace the cooked noodles in bowls.\r\n\r\nPour the sauce over the noodles.\r\n\r\nGarnish with cucumber slices if desired.\r\n\r\nServe immediately and enjoy!',30,NULL,'2025-10-06 08:45:15.754552','2025-10-06 08:45:18.640418',NULL,NULL,NULL),(19,4,'🥞 Kimchi Jeon (Kimchi Pancake)','🍜 1 cup all-purpose flour\r\n\r\n🥄 1 tablespoon rice flour (optional, for extra crispiness)\r\n\r\n💧 1/2 cup kimchi juice (or water)\r\n\r\n🥚 1 egg\r\n\r\n🧂 1/2 teaspoon salt\r\n\r\n🌶️ 1/2 teaspoon gochugaru (Korean chili flakes, optional)\r\n\r\n🧄 1/2 cup chopped kimchi (well-drained)\r\n\r\n🧅 2 spring onions, chopped\r\n\r\n🥄 1 tablespoon vegetable oil (for frying)\r\n\r\n🍋 Soy sauce and vinegar for dipping (optional)','Prepare the Batter:\r\n\r\nIn a mixing bowl, combine all-purpose flour, rice flour (if using), kimchi juice (or water), egg, salt, and gochugaru.\r\n\r\nWhisk until the batter is smooth and well combined.\r\n\r\nAdd Kimchi and Spring Onions:\r\n\r\nFold in the chopped kimchi and spring onions into the batter.\r\n\r\nCook the Pancake:\r\n\r\nHeat a non-stick pan over medium heat and add vegetable oil.\r\n\r\nPour the batter into the pan, spreading it evenly to form a thin pancake.\r\n\r\nCook for about 3–4 minutes on each side, or until golden brown and crispy.\r\n\r\nServe:\r\n\r\nRemove the pancake from the pan and place it on a paper towel to drain excess oil.\r\n\r\nCut into wedges and serve with a dipping sauce made of soy sauce and vinegar, if desired.',15,NULL,'2025-10-06 08:46:14.493759','2025-10-06 08:46:14.714829',NULL,NULL,NULL),(20,4,'🍜 Japchae (Korean Glass Noodles)','🍜 250g dangmyeon (sweet potato glass noodles)\r\n\r\n🥩 150g beef (sirloin or rib-eye), thinly sliced\r\n\r\n🧅 1 medium onion, thinly sliced\r\n\r\n🥕 1 medium carrot, julienned\r\n\r\n🍄 5–6 shiitake mushrooms, thinly sliced\r\n\r\n🌿 1 cup spinach, blanched and chopped\r\n\r\n🧄 2 cloves garlic, minced\r\n\r\n🥄 2 tablespoons sesame oil\r\n\r\n🥄 2 tablespoons soy sauce\r\n\r\n🥄 1 tablespoon sugar\r\n\r\n🥄 1 tablespoon sesame seeds\r\n\r\n🧂 Salt and pepper, to taste\r\n\r\n🧂 1 tablespoon vegetable oil (for stir-frying)','Marinate the Beef:\r\n\r\nIn a bowl, combine the thinly sliced beef with 1 tablespoon of soy sauce, 1 teaspoon of sesame oil, and a pinch of black pepper. Let it marinate for at least 10 minutes.\r\n\r\nPrepare the Noodles:\r\n\r\nBring a pot of water to a boil. Add the dangmyeon noodles and cook according to the package instructions (usually 6–8 minutes). Drain and rinse under cold water. Drizzle with 1 tablespoon of sesame oil to prevent sticking and set aside.\r\n\r\nStir-Fry the Vegetables:\r\n\r\nHeat vegetable oil in a large pan over medium heat. Add the minced garlic and sauté until fragrant.\r\n\r\nAdd the sliced onion and carrot to the pan, stir-frying until they begin to soften.\r\n\r\nAdd the shiitake mushrooms and continue to stir-fry until all vegetables are tender.\r\n\r\nCook the Beef:\r\n\r\nIn the same pan, push the vegetables to one side and add the marinated beef. Stir-fry until the beef is cooked through.\r\n\r\nCombine Noodles and Vegetables:\r\n\r\nAdd the cooked noodles to the pan with the beef and vegetables. Pour in the remaining 1 tablespoon of soy sauce and 1 tablespoon of sugar. Toss everything together until well combined and heated through.\r\n\r\nAdd Spinach and Final Seasoning:\r\n\r\nAdd the blanched and chopped spinach to the pan. Toss to combine.\r\n\r\nSprinkle with sesame seeds and adjust seasoning with salt and pepper to taste.\r\n\r\nServe:\r\n\r\nTransfer the japchae to a serving dish. Serve warm or at room temperature.',35,NULL,'2025-10-06 08:47:05.037868','2025-10-06 08:47:05.221073',NULL,NULL,NULL),(21,4,'🌶️ Tteokbokki (Korean Spicy Rice Cake)','🍚 300g Korean rice cakes (tteok)\r\n\r\n🍲 150g fish cakes, sliced\r\n\r\n🧅 1 small onion, sliced\r\n\r\n🧄 2 cloves garlic, minced\r\n\r\n🥄 2 tablespoons gochujang (Korean red chili paste)\r\n\r\n🥄 1 tablespoon gochugaru (Korean red chili flakes)\r\n\r\n🥄 1 tablespoon sugar\r\n\r\n🥄 1 tablespoon soy sauce\r\n\r\n💧 2 cups water or anchovy broth\r\n\r\n🥄 1 tablespoon sesame oil\r\n\r\n🥚 1 hard-boiled egg (optional)\r\n\r\n🌿 1 stalk green onion, chopped\r\n\r\n🌰 1 teaspoon sesame seeds\r\n\r\n🧂 Salt, to taste','Soak the Rice Cakes:\r\n\r\nIf using dried rice cakes, soak them in warm water for about 30 minutes until softened. Drain and set aside.\r\n\r\nPrepare the Sauce:\r\n\r\nIn a bowl, mix together gochujang, gochugaru, sugar, soy sauce, and a pinch of salt.\r\n\r\nCook the Base:\r\n\r\nIn a large pan, combine the water or anchovy broth with the prepared sauce. Bring to a boil over medium heat.\r\n\r\nAdd the Rice Cakes:\r\n\r\nAdd the soaked rice cakes to the pan. Reduce heat to medium-low and simmer for about 10 minutes, stirring occasionally, until the sauce thickens and the rice cakes are tender.\r\n\r\nAdd Fish Cakes and Onion:\r\n\r\nAdd the sliced fish cakes and onion to the pan. Continue to simmer for an additional 5 minutes, allowing the flavors to meld.\r\n\r\nFinal Touches:\r\n\r\nStir in the minced garlic and sesame oil. Cook for another 2 minutes.\r\n\r\nServe:\r\n\r\nTransfer the tteokbokki to a serving plate. Garnish with chopped green onion, sesame seeds, and a hard-boiled egg if desired.',35,NULL,'2025-10-06 08:48:09.752028','2025-10-06 08:48:13.815544',NULL,NULL,NULL),(22,4,'🍣 Gimbap (Korean Rice Rolls)','Ingredients\r\n\r\n🍚 2 cups cooked short-grain rice (preferably warm)\r\n\r\n🥄 1 tablespoon sesame oil\r\n\r\n🥄 1 tablespoon sesame seeds\r\n\r\n🧂 Salt, to taste\r\n\r\n🍣 5–6 sheets of dried seaweed (gim/nori)\r\n\r\n🥕 1 small carrot, julienned\r\n\r\n🥬 1 cup spinach, blanched and chopped\r\n\r\n🥒 1 cucumber, julienned\r\n\r\n🍳 1 egg, scrambled and cooked into a thin omelet, then sliced into strips\r\n\r\n🥒 1/2 cup pickled radish (danmuji), sliced into strips\r\n\r\n🥩 100g cooked beef (bulgogi-style), sliced into strips (optional)\r\n\r\n🥄 Soy sauce and wasabi for dipping (optional)','Prepare the Rice:\r\n\r\nIn a bowl, mix the warm cooked rice with sesame oil, sesame seeds, and a pinch of salt. Set aside.\r\n\r\nPrepare the Fillings:\r\n\r\nJulienne the carrot and cucumber.\r\n\r\nBlanch the spinach in boiling water for 1 minute, then rinse under cold water. Squeeze out excess water and chop.\r\n\r\nCook the egg into a thin omelet, then slice into strips.\r\n\r\nIf using, slice the cooked beef into strips.\r\n\r\nAssemble the Gimbap:\r\n\r\nPlace a sheet of seaweed on a bamboo sushi mat, shiny side down.\r\n\r\nSpread a thin layer of seasoned rice over the seaweed, leaving about 2 cm at the top edge.\r\n\r\nArrange the fillings (carrot, spinach, cucumber, egg, pickled radish, and beef) horizontally across the center of the rice.\r\n\r\nRoll the Gimbap:\r\n\r\nLift the edge of the bamboo mat closest to you and begin rolling tightly, pressing gently to keep the roll firm.\r\n\r\nSeal the edge with a little water.\r\n\r\nSlice and Serve:\r\n\r\nUsing a sharp knife, slice the roll into bite-sized pieces.\r\n\r\nServe with soy sauce and wasabi for dipping, if desired.',30,NULL,'2025-10-06 08:49:50.625161','2025-10-06 08:49:50.868685',NULL,NULL,NULL),(23,4,'🍉 Hwachae (Korean Fruit Punch)','🍉 1 small watermelon, cut into small cubes\r\n\r\n🍓 1 cup strawberries, hulled and sliced\r\n\r\n🍍 1/2 cup pineapple, diced\r\n\r\n🍊 1 orange, peeled and segmented\r\n\r\n🍇 1/2 cup green grapes, halved\r\n\r\n🍑 1/2 cup peaches, diced (fresh or canned)\r\n\r\n🥥 1/2 cup coconut jelly or agar agar cubes\r\n\r\n🥄 2 tablespoons honey or sugar (adjust to taste)\r\n\r\n🥄 1 tablespoon lemon juice\r\n\r\n🧊 Ice cubes\r\n\r\n🥤 2 cups sparkling water or lemon-lime soda','Prepare the Fruits:\r\n\r\nWash and prepare all the fruits as described above.\r\n\r\nIf using canned peaches, drain them well.\r\n\r\nMake the Syrup:\r\n\r\nIn a small saucepan, combine honey (or sugar) and lemon juice with 1/2 cup of water.\r\n\r\nHeat over low heat, stirring until the sweetener dissolves completely.\r\n\r\nRemove from heat and let it cool.\r\n\r\nAssemble the Hwachae:\r\n\r\nIn a large mixing bowl, combine all the prepared fruits and coconut jelly or agar agar cubes.\r\n\r\nPour the cooled syrup over the fruit mixture and gently toss to combine.\r\n\r\nServe:\r\n\r\nJust before serving, add ice cubes to the fruit mixture.\r\n\r\nPour sparkling water or lemon-lime soda over the fruits and ice.\r\n\r\nGently stir to combine, ensuring the fruits are evenly distributed.\r\n\r\nGarnish and Enjoy:\r\n\r\nServe the hwachae in individual bowls or glasses.\r\n\r\nGarnish with additional mint leaves or edible flowers if desired.\r\n\r\nEnjoy this refreshing and colorful Korean fruit punch!',10,NULL,'2025-10-06 08:50:42.968648','2025-10-06 08:50:43.230139',NULL,NULL,NULL),(24,4,'🍗 Samgyetang (Korean Ginseng Chicken Soup)','🥣 1 whole young chicken (about 500g–600g), cleaned and patted dry\r\n\r\n🌿 1 tablespoon ginseng root (or ginseng powder)\r\n\r\n🍚 1/4 cup sweet rice (also known as glutinous rice)\r\n\r\n🧄 4–5 cloves garlic, peeled\r\n\r\n🍄 2–3 dried jujube dates (optional)\r\n\r\n🥬 2–3 sprigs of fresh ginseng leaves (optional, for garnish)\r\n\r\n🧂 Salt and pepper, to taste\r\n\r\n💧 6 cups water','Prepare the Rice:\r\n\r\nRinse the sweet rice under cold water until the water runs clear. Drain and set aside.\r\n\r\nStuff the Chicken:\r\n\r\nStuff the cleaned chicken cavity with the soaked sweet rice, garlic cloves, and dried jujube dates.\r\n\r\nSecure the opening with kitchen twine or toothpicks.\r\n\r\nCook the Soup:\r\n\r\nPlace the stuffed chicken in a large pot and add the ginseng root and water.\r\n\r\nBring to a boil over high heat, then reduce the heat to low and simmer for about 1 hour and 30 minutes, or until the chicken is tender and the flavors are well combined.\r\n\r\nSeason the Soup:\r\n\r\nRemove the chicken from the pot and discard the kitchen twine or toothpicks.\r\n\r\nSeason the broth with salt and pepper to taste.\r\n\r\nServe:\r\n\r\nPlace the whole chicken in a serving bowl and pour the hot broth over it.\r\n\r\nGarnish with fresh ginseng leaves if desired.\r\n\r\nServe hot and enjoy the nourishing and flavorful Samgyetang!',120,NULL,'2025-10-06 08:53:12.758993','2025-10-06 08:53:12.968518',NULL,NULL,NULL),(25,4,'🍲 Kimchi Jjigae (Korean Kimchi Stew)','🥣 2 cups well-fermented kimchi, chopped\r\n\r\n🥩 150g pork belly or shoulder, sliced\r\n\r\n🧄 2 cloves garlic, minced\r\n\r\n🧅 1 small onion, sliced\r\n\r\n🍄 100g tofu, cubed\r\n\r\n🥄 1 tablespoon gochujang (Korean red chili paste)\r\n\r\n🥄 1 tablespoon gochugaru (Korean red chili flakes)\r\n\r\n🥄 1 tablespoon soy sauce\r\n\r\n🥄 1 teaspoon sesame oil\r\n\r\n💧 3 cups water or anchovy broth\r\n\r\n🧂 Salt and pepper, to taste\r\n\r\n🌿 1 stalk green onion, chopped (for garnish)\r\n\r\n🍚 Steamed rice, for serving','Sauté the Pork and Aromatics:\r\n\r\nIn a pot, heat sesame oil over medium heat.\r\n\r\nAdd the sliced pork and cook until browned.\r\n\r\nAdd the minced garlic and sliced onion, sautéing until fragrant.\r\n\r\nAdd the Kimchi and Seasonings:\r\n\r\nAdd the chopped kimchi to the pot and stir well.\r\n\r\nMix in the gochujang, gochugaru, soy sauce, and a pinch of salt and pepper.\r\n\r\nSimmer the Stew:\r\n\r\nPour in the water or anchovy broth, bringing the mixture to a boil.\r\n\r\nReduce the heat to low and let it simmer for about 10 minutes, allowing the flavors to meld.\r\n\r\nAdd the Tofu:\r\n\r\nGently add the cubed tofu to the pot, simmering for an additional 5 minutes.\r\n\r\nFinal Seasoning:\r\n\r\nTaste the stew and adjust the seasoning with salt and pepper as needed.\r\n\r\nServe:\r\n\r\nLadle the kimchi jjigae into bowls, garnishing with chopped green onions.\r\n\r\nServe hot with steamed rice on the side.',30,NULL,'2025-10-06 08:56:41.002690','2025-10-06 08:56:41.719295',NULL,NULL,NULL),(26,4,'🍚 Bibimbap (Korean Mixed Rice)','🍚 2 cups cooked short-grain rice (preferably warm)\r\n\r\n🥩 150g ground beef or chicken\r\n\r\n🥄 1 tablespoon soy sauce\r\n\r\n🥄 1 tablespoon sesame oil\r\n\r\n🥄 1 tablespoon gochujang (Korean red chili paste)\r\n\r\n🥄 1 teaspoon sugar\r\n\r\n🧄 2 cloves garlic, minced\r\n\r\n🥕 1 small carrot, julienned\r\n\r\n🥒 1/2 cucumber, julienned\r\n\r\n🍄 100g shiitake mushrooms, sliced\r\n\r\n🥬 1 cup spinach, blanched and chopped\r\n\r\n🥚 1 egg\r\n\r\n🌿 1 sheet nori (seaweed), cut into strips\r\n\r\n🥄 1 tablespoon sesame seeds\r\n\r\n🧂 Salt and pepper, to taste\r\n\r\n🥄 1 tablespoon vegetable oil (for cooking)','Prepare the Vegetables:\r\n\r\nJulienne the carrot and cucumber.\r\n\r\nSlice the shiitake mushrooms.\r\n\r\nBlanch the spinach in boiling water for 1 minute, then rinse under cold water. Squeeze out excess water and chop.\r\n\r\nCook the Ground Meat:\r\n\r\nIn a pan, heat 1 tablespoon of vegetable oil over medium heat.\r\n\r\nAdd the minced garlic and sauté until fragrant.\r\n\r\nAdd the ground meat and cook until browned.\r\n\r\nSeason with 1 tablespoon of soy sauce, 1 tablespoon of sesame oil, 1 tablespoon of gochujang, and 1 teaspoon of sugar. Stir well and cook for an additional 2 minutes.\r\n\r\nCook the Vegetables:\r\n\r\nIn separate pans, sauté the carrot, cucumber, and shiitake mushrooms with a little sesame oil until tender. Season each with a pinch of salt.\r\n\r\nIn the same pan, sauté the spinach until wilted. Season with a pinch of salt and a drizzle of sesame oil.\r\n\r\nFry the Egg:\r\n\r\nIn a pan, heat a little vegetable oil over medium heat.\r\n\r\nCrack the egg into the pan and fry until the white is set but the yolk remains runny.\r\n\r\nAssemble the Bibimbap:\r\n\r\nIn a bowl, place the cooked rice as the base.\r\n\r\nArrange the cooked vegetables and ground meat on top of the rice in sections.\r\n\r\nPlace the fried egg in the center.\r\n\r\nSprinkle with sesame seeds and nori strips.\r\n\r\nServe:\r\n\r\nServe with additional gochujang on the side.\r\n\r\nTo eat, mix all the ingredients together thoroughly before enjoying.',30,NULL,'2025-10-06 09:02:22.180309','2025-10-06 09:02:23.051926',NULL,NULL,NULL),(27,1,'Gyudon (Japanese Beef Bowl) 🐮💓','🥩 Beef slices (thinly sliced) – 200g\r\n🧅 Onion – 1 (sliced)\r\n🍶 Soy sauce – 2 tbsp\r\n🍶 Mirin – 2 tbsp\r\n🍶 Sake (optional) – 1 tbsp\r\n🍬 Sugar – 1 tbsp\r\n💧 Water / dashi – ½ cup\r\n🍚 Steamed rice – 1 bowl\r\n🥚 Egg yolk or onsen egg – optional ','1️⃣In a pan, add onion + water + seasonings 🍶🧅\r\n2️⃣ Let it simmer till onion is soft 💨\r\n3️⃣ Add beef slices 🥩 and cook till tender 💕\r\n4️⃣ Pour over warm rice 🍚✨\r\n5️⃣ Top with egg yolk & pickled ginger if you like 🥚💗\r\n\r\n💬 Caption idea:',15,NULL,'2025-10-07 01:42:51.816072','2025-10-07 01:42:54.075326',NULL,NULL,NULL),(28,1,'🍚 Chicken Katsudon 🐔','🍗 Chicken breast (boneless) – 1 pc\r\n🧂 Salt & pepper – to taste\r\n🌾 Flour – ¼ cup\r\n🥚 Egg – 1 (beaten)\r\n🍞 Breadcrumbs (panko or regular) – ½ cup\r\n🛢️ Oil – for frying\r\n\r\n🍶 Sauce & Egg Mix:\r\n🧅 Onion – ½ (sliced)\r\n🍶 Soy sauce – 2 tbsp (use halal-certified)\r\n🍬 Sugar – 1 tbsp\r\n🍶 Mirin substitute – 2 tbsp (use apple juice or honey 🍯)\r\n💧 Water or dashi – ¼ cup\r\n🥚 Egg – 1 (lightly beaten)','1️⃣ Season chicken with salt & pepper 🧂💛\r\n2️⃣ Coat in flour → egg → breadcrumbs 🫶\r\n3️⃣ Deep fry till golden & crispy 🐥✨\r\n4️⃣ In a pan, simmer onion + sauce mix till soft 🧅💦\r\n5️⃣ Slice the fried chicken & place on top 🍗\r\n6️⃣ Pour beaten egg around, cover & cook 1–2 mins 🥚💨\r\n7️⃣ Serve over hot rice 🍚💖\r\n\r\n💬 Cute Caption Idea:\r\n“Katsudon but make it halal & cozy 🍱💗 crispy outside, fluffy egg inside 💛',30,NULL,'2025-10-07 01:46:05.446560','2025-10-07 01:46:06.098702',NULL,NULL,NULL),(29,1,'Oyakodon (Japanese Chicken & Egg Bowl) 🐔🍚','🍗 Chicken thigh or breast – 1 pc (cut bite-size)\r\n🧅 Onion – ½ (sliced thinly)\r\n🍶 Soy sauce (halal-certified) – 2 tbsp\r\n🍬 Sugar – 1 tbsp\r\n🍶 Mirin substitute – 2 tbsp (apple juice 🍏 or honey 🍯)\r\n💧 Water or dashi – ¼ cup\r\n🥚 Eggs – 2 (lightly beaten)\r\n🍚 Steamed rice – 1 bowl\r\n🌿 Spring onions – for garnish 🌸','1️⃣ In a small pan, add onion + soy sauce + sugar + mirin sub + water 💧🧅\r\n2️⃣ Let it simmer till onion turns soft 💕\r\n3️⃣ Add chicken & cook till fully cooked 🐔🔥\r\n4️⃣ Pour in beaten eggs gently 🥚💛\r\n5️⃣ Cover & cook until eggs are soft-set (not too firm!) ✨\r\n6️⃣ Serve over warm rice 🍚💕\r\n7️⃣ Sprinkle spring onions 🌿 and enjoy your cozy bowl! 😍🍱\r\n\r\n💬 Cute Caption Idea:\r\n“Oyakodon = warmth in a bowl 🍚💖 chicken + egg = perfect pair',25,NULL,'2025-10-07 01:48:03.343041','2025-10-07 01:48:03.938894',NULL,NULL,NULL),(30,1,'Miso Soup (Japanese Comfort Bowl) 🍃','💧 Water – 2 cups\r\n🧂 Halal dashi substitute – 1 tsp (use veggie stock or kombu broth 🌿)\r\n🥄 Miso paste (check halal label) – 2 tbsp\r\n🌱 Tofu (soft) – ½ cup, cubed\r\n🌿 Wakame (dried seaweed) – 1 tbsp (soak before use)\r\n🧅 Spring onions – for garnish 🌸','1️⃣ In a pot, heat water + halal dashi until warm 💧🔥\r\n2️⃣ Add tofu & wakame, simmer for 2–3 mins 🍃🫶\r\n3️⃣ Turn off heat & stir in miso paste (don’t boil miso!) 🥄💛\r\n4️⃣ Mix gently till dissolved 💕\r\n5️⃣ Serve hot & sprinkle spring onions 🌿✨',15,NULL,'2025-10-07 01:52:13.800350','2025-10-07 01:52:14.248064',NULL,NULL,NULL),(31,1,'Tuna Mayo Onigiri (Japanese Rice Ball) 🐟🍙','🍚 Cooked Japanese rice – 1½ cups (warm, not hot)\r\n🐟 Canned tuna (in water or oil) – 1 can (drain well)\r\n🍶 Mayonnaise (halal) – 2 tbsp\r\n🧂 Salt – a pinch\r\n🌿 Nori seaweed sheets – for wrapping\r\n🌸 Optional: sesame seeds, spring onions 🌼','1️⃣ In a bowl, mix tuna + mayo + a pinch of salt 🐟💫\r\n2️⃣ Wet your hands & sprinkle a bit of salt ✋🧂\r\n3️⃣ Take a scoop of rice → flatten slightly 🍚💕\r\n4️⃣ Add tuna mayo filling inside → close & shape into a triangle or ball 🍙💖\r\n5️⃣ Wrap with a strip of nori 🌿✨\r\n6️⃣ Sprinkle sesame seeds if you want extra cuteness 🌸😋',15,NULL,'2025-10-07 01:55:28.828748','2025-10-07 01:55:29.210573',NULL,NULL,NULL),(32,1,'Omurice (Japanese Omelette Rice) 🍅','🍚 Cooked rice – 1 cup (preferably cold)\r\n🍗 Chicken breast (diced) – ½ cup\r\n🧅 Onion – ¼ (chopped)\r\n🌽 Mixed veggies – 2 tbsp (optional 🥕🌽)\r\n🍅 Ketchup – 2 tbsp\r\n🧂 Salt & pepper – to taste\r\n🛢️ Oil – 1 tbsp\r\n\r\n🥚 Omelette:\r\n🥚 Eggs – 2\r\n🥛 Milk – 1 tbsp (makes it fluffy 💕)\r\n🧂 Pinch of salt\r\n🧈 Butter or oil – for frying','1️⃣ Heat oil in a pan → sauté onion & chicken till cooked 🐔💫\r\n2️⃣ Add veggies + rice + ketchup + seasoning 🍅🍚 mix well!\r\n3️⃣ Shape fried rice into an oval mound on a plate 🍱✨\r\n4️⃣ In another pan, whisk eggs + milk + salt → cook softly 💛\r\n5️⃣ Slide the omelette over the rice 🥹💕\r\n6️⃣ Drizzle extra ketchup (draw a cute heart ❤️ or smile 😊)',30,NULL,'2025-10-07 01:59:37.156709','2025-10-07 01:59:37.536559',NULL,NULL,NULL),(33,1,'🍛 Halal Japanese Curry Rice 🍗🥕','🍗 Chicken / beef (halal) – 200g (bite-size pieces)\r\n🧅 Onion – 1 (sliced)\r\n🥔 Potato – 1 (cubed)\r\n🥕 Carrot – 1 (sliced)\r\n🧄 Garlic – 2 cloves (minced)\r\n🛢️ Oil – 1 tbsp\r\n\r\n🍛 Curry Sauce:\r\n🍶 Halal Japanese curry roux (or homemade paste) – 2–3 cubes\r\n💧 Water – 2 cups\r\n🍯 Optional: 1 tsp honey or apple 🍎 (for sweetness)\r\n\r\n🍚 Serve with:\r\nSteamed rice 🍚 ','1️⃣ Heat oil → sauté onion & garlic till soft 🧅💫\r\n2️⃣ Add chicken, cook till slightly browned 🍗✨\r\n3️⃣ Add potatoes & carrots 🥕🥔 stir well 💕\r\n4️⃣ Pour in water & simmer till veggies are tender 💦\r\n5️⃣ Add curry roux cubes → stir until sauce thickens 🍛😋\r\n6️⃣ Serve over hot rice 🍚❤️',40,NULL,'2025-10-07 02:03:45.923962','2025-10-07 02:03:46.548593',NULL,NULL,NULL),(34,1,'🍗✨ Halal Chicken Karaage (Japanese Fried Chicken)','🍗 Chicken thigh (boneless) – 300g (cut bite-size)\r\n🧄 Garlic – 2 cloves (minced)\r\n🧉 Ginger – 1 tsp (grated)\r\n🍶 Soy sauce (halal) – 2 tbsp\r\n🍶 Mirin substitute – 1 tbsp (apple juice 🍏 or honey 🍯)\r\n🧂 Salt & pepper – to taste\r\n🌾 Cornstarch or potato starch – ½ cup\r\n🛢️ Oil – for deep frying\r\n\r\n🍋 Optional: Lemon wedges 🍋 & mayo 🍶 for dipping','1️⃣ In a bowl, mix chicken + soy sauce + ginger + garlic + mirin sub 🧄💫\r\n2️⃣ Marinate 15–30 mins (or longer for more flavor 💕)\r\n3️⃣ Coat each piece in cornstarch evenly 🌾✨\r\n4️⃣ Deep fry until golden & crispy (about 5–6 mins) 🔥🍗\r\n5️⃣ Drain on paper towel & serve hot 🍋💛',20,NULL,'2025-10-07 02:07:27.434471','2025-10-07 02:07:27.811587',NULL,NULL,NULL),(35,1,'🍓🥪 Japanese Strawberry Sando (Fruit Sandwich)','🍞 Soft white bread (crustless) – 2 slices\r\n🍓 Fresh strawberries – 4–6 (medium size)\r\n🥛 Whipped cream – ½ cup (or fresh cream + sugar)\r\n🍬 Sugar – 1 tsp (optional, for extra sweetness 💖)\r\n\r\n✨ Optional: Kiwi 🥝, mango 🥭, or grapes 🍇 for colorful mix!','1️⃣ Whip cream till thick & fluffy 🍦💫\r\n2️⃣ Spread a layer of cream on one bread slice 🍞💕\r\n3️⃣ Place strawberries neatly (tips facing up 🍓✨)\r\n4️⃣ Add more cream on top → cover with second slice 🍞🤍\r\n5️⃣ Wrap tightly in plastic wrap & chill 30 mins 🧊💛\r\n6️⃣ Slice diagonally (so the cute strawberries show!) 💕🔪',20,NULL,'2025-10-07 02:11:09.229060','2025-10-07 02:11:10.054464',NULL,NULL,NULL),(36,1,'🥪✨ Japanese Egg Sando (Tamago Sandwich)','🍞 Soft white bread (crustless) – 2 slices\r\n🥚 Eggs – 2\r\n🥛 Mayonnaise (halal) – 2 tbsp\r\n🧂 Salt & pepper – a pinch\r\n🥄 Optional: mustard, chives, or lettuce 🌿','1️⃣ Boil eggs for 7–8 mins → cool & peel 🥚💧\r\n2️⃣ Mash eggs in a bowl + mayo + salt & pepper 🥄✨\r\n3️⃣ Spread egg mixture evenly on one bread slice 🍞💛\r\n4️⃣ Add lettuce or chives if desired 🌿💕\r\n5️⃣ Cover with second bread slice → press gently 🥪💖\r\n6️⃣ Slice diagonally for cute triangles ✨🔪',15,NULL,'2025-10-07 02:14:23.054274','2025-10-07 02:14:23.610303',NULL,NULL,NULL),(37,1,'🥞 Dorayaki (Japanese Red Bean Pancakes) 🍯','🥚 Eggs – 2\r\n🍚 Sugar – 50g\r\n🍯 Honey – 1 tbsp\r\n🍶 Milk – 50ml\r\n🌾 Plain flour – 100g\r\n🛢️ Oil – for greasing\r\n🍡 Filling: Halal red bean paste (anko) – 100g','1️⃣ Whisk eggs + sugar + honey until fluffy 🥚✨\r\n2️⃣ Add milk → mix well 💛\r\n3️⃣ Sift in flour → fold gently 🌾💕\r\n4️⃣ Heat a non-stick pan → lightly oil 🛢️\r\n5️⃣ Pour small circles of batter (≈6cm) 🥞💫\r\n6️⃣ Cook until bubbles form → flip & cook other side 🔄\r\n7️⃣ Sandwich 1 tbsp red bean paste between 2 pancakes 🍡💖',20,NULL,'2025-10-07 02:18:38.559041','2025-10-07 02:18:39.182294',NULL,NULL,NULL),(38,1,'🥞 Dorayaki (Japanese Red Bean Pancakes) 🍯','🥚 Eggs – 2\r\n🍚 Sugar – 50g\r\n🍯 Honey – 1 tbsp\r\n🍶 Milk – 50ml\r\n🌾 Plain flour – 100g\r\n🛢️ Oil – for greasing\r\n🍡 Filling: Halal red bean paste (anko) – 100g','1️⃣ Whisk eggs + sugar + honey until fluffy 🥚✨\r\n2️⃣ Add milk → mix well 💛\r\n3️⃣ Sift in flour → fold gently 🌾💕\r\n4️⃣ Heat a non-stick pan → lightly oil 🛢️\r\n5️⃣ Pour small circles of batter (≈6cm) 🥞💫\r\n6️⃣ Cook until bubbles form → flip & cook other side 🔄\r\n7️⃣ Sandwich 1 tbsp red bean paste between 2 pancakes 🍡💖',20,NULL,'2025-10-07 02:18:39.208309','2025-10-07 02:18:39.712954',NULL,NULL,NULL);
